namespace sv_02c87213892c4175b5f40816fa2190ed.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service that holds per-circuit theme state and notifies subscribers
/// when values change. Each SignalR circuit (user) gets its own instance.
/// </summary>
public sealed class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0d6efd"; // Bootstrap primary blue

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    /// <summary>
    /// Raised whenever Theme or AccentColor changes. Interactive components
    /// subscribe to this to call StateHasChanged().
    /// </summary>
    public event Action? OnChange;

    /// <summary>
    /// Bulk-update both values, raising OnChange only once.
    /// </summary>
    public void SetPreferences(ThemeMode theme, string accentColor)
    {
        bool changed = false;
        if (_theme != theme) { _theme = theme; changed = true; }
        if (_accentColor != accentColor) { _accentColor = accentColor; changed = true; }
        if (changed) NotifyChanged();
    }

    private void NotifyChanged() => OnChange?.Invoke();
}

// Theme interop — applies theme visually via CSS and persists to a cookie
// so the static SSR layout can read it on the next navigation.

export function applyTheme(theme, accentColor) {
    const root = document.documentElement;

    // Resolve "system" to actual preference
    let effective = theme.toLowerCase();
    if (effective === "system") {
        effective = window.matchMedia("(prefers-color-scheme: dark)").matches
            ? "dark" : "light";
    }

    root.setAttribute("data-bs-theme", effective);
    root.style.setProperty("--app-accent-color", accentColor);

    // Persist to cookie (SameSite=Strict, 400-day max per spec)
    const expires = new Date(Date.now() + 400 * 864e5).toUTCString();
    document.cookie = `app_theme=${theme};path=/;expires=${expires};SameSite=Strict`;
    document.cookie = `app_accent=${encodeURIComponent(accentColor)};path=/;expires=${expires};SameSite=Strict`;
}

export function getSystemThemePreference() {
    return window.matchMedia("(prefers-color-scheme: dark)").matches
        ? "dark" : "light";
}

