+// Theme interop — applies theme visually via CSS and persists to a cookie
+// so the static SSR layout can read it on the next navigation.
+
+export function applyTheme(theme, accentColor) {
+    const root = document.documentElement;
+
+    // Resolve "system" to actual preference
+    let effective = theme.toLowerCase();
+    if (effective === "system") {
+        effective = window.matchMedia("(prefers-color-scheme: dark)").matches
+            ? "dark" : "light";
+    }
+
+    root.setAttribute("data-bs-theme", effective);
+    root.style.setProperty("--app-accent-color", accentColor);
+
+    // Persist to cookie (SameSite=Strict, 400-day max per spec)
+    const expires = new Date(Date.now() + 400 * 864e5).toUTCString();
+    document.cookie = `app_theme=${theme};path=/;expires=${expires};SameSite=Strict`;
+    document.cookie = `app_accent=${encodeURIComponent(accentColor)};path=/;expires=${expires};SameSite=Strict`;
+}
+
+export function getSystemThemePreference() {
+    return window.matchMedia("(prefers-color-scheme: dark)").matches
+        ? "dark" : "light";
+}
+

