@* Interactive island embedded in the static layout.
   It subscribes to ThemeService.OnChange so it updates when ANY
   interactive component changes the theme (e.g., the Settings page). *@

@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService
@inject IJSRuntime JS

<span class="theme-indicator d-flex align-items-center gap-2">
    <span class="badge"
          style="background-color: @ThemeService.AccentColor;">
        @ThemeLabel
    </span>
    <button class="btn btn-sm btn-outline-secondary" @onclick="CycleTheme"
            title="Toggle theme">
        @ThemeIcon
    </button>
</span>

@code {
    private IJSObjectReference? _module;

    private string ThemeLabel => ThemeService.Theme switch
    {
        ThemeMode.Dark   => "Dark",
        ThemeMode.Light  => "Light",
        _                => "System"
    };

    private string ThemeIcon => ThemeService.Theme switch
    {
        ThemeMode.Dark   => "🌙",
        ThemeMode.Light  => "☀️",
        _                => "💻"
    };

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./js/theme-interop.js");

            // Apply the current theme to the DOM immediately
            await ApplyThemeAsync();

            ThemeService.OnChange += HandleThemeChanged;
        }
    }

    private async void HandleThemeChanged()
    {
        await InvokeAsync(async () =>
        {
            await ApplyThemeAsync();
            StateHasChanged();
        });
    }

    private async Task ApplyThemeAsync()
    {
        if (_module is not null)
        {
            await _module.InvokeVoidAsync("applyTheme",
                ThemeService.Theme.ToString(), ThemeService.AccentColor);
        }
    }

    private async Task CycleTheme()
    {
        ThemeService.Theme = ThemeService.Theme switch
        {
            ThemeMode.Light  => ThemeMode.Dark,
            ThemeMode.Dark   => ThemeMode.System,
            _                => ThemeMode.Light
        };
        // ApplyThemeAsync is called by HandleThemeChanged
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService
@inject IJSRuntime JS

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card" style="max-width: 480px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="mb-3">
            <label class="form-label">Mode</label>
            <select class="form-select" value="@ThemeService.Theme"
                    @onchange="OnThemeSelected">
                @foreach (var mode in Enum.GetValues<ThemeMode>())
                {
                    <option value="@mode">@mode</option>
                }
            </select>
        </div>

        <div class="mb-3">
            <label class="form-label">Accent Color</label>
            <div class="d-flex align-items-center gap-2">
                <input type="color" class="form-control form-control-color"
                       value="@ThemeService.AccentColor"
                       @onchange="OnAccentChanged" />
                <span class="text-muted">@ThemeService.AccentColor</span>
            </div>
        </div>

        <div class="alert alert-info mb-0">
            Current theme: <strong>@ThemeService.Theme</strong> &middot;
            Accent: <span style="color: @ThemeService.AccentColor;">■</span>
            <code>@ThemeService.AccentColor</code>
        </div>
    </div>
</div>

@code {
    private IJSObjectReference? _module;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./js/theme-interop.js");
            ThemeService.OnChange += HandleThemeChanged;
        }
    }

    private async Task OnThemeSelected(ChangeEventArgs e)
    {
        if (Enum.TryParse<ThemeMode>(e.Value?.ToString(), out var mode))
        {
            ThemeService.Theme = mode;
        }
    }

    private async Task OnAccentChanged(ChangeEventArgs e)
    {
        ThemeService.AccentColor = e.Value?.ToString() ?? ThemeService.AccentColor;
    }

    private async void HandleThemeChanged()
    {
        await InvokeAsync(async () =>
        {
            if (_module is not null)
            {
                await _module.InvokeVoidAsync("applyTheme",
                    ThemeService.Theme.ToString(), ThemeService.AccentColor);
            }
            StateHasChanged();
        });
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

