@inject IHttpContextAccessor HttpContextAccessor

@{
    // Read theme cookie so the very first SSR render has the right attribute.
    var themeCookie = HttpContextAccessor.HttpContext?.Request.Cookies["app_theme"] ?? "System";
    var accentCookie = HttpContextAccessor.HttpContext?.Request.Cookies["app_accent"] ?? "#0d6efd";
    accentCookie = Uri.UnescapeDataString(accentCookie);

    var bsTheme = themeCookie.ToLowerInvariant() switch
    {
        "dark" => "dark",
        "light" => "light",
        _ => "" // system — let the browser/JS decide
    };
}

<!DOCTYPE html>
<html lang="en" @(string.IsNullOrEmpty(bsTheme) ? null : $"data-bs-theme=\"{bsTheme}\"")
      style="--app-accent-color: @accentCookie;">

<head>

